-- SELECT-only (no writes): run once after migration 20261109220000 is applied (Provider Catalogue filter speed), from a Supabase SQL session (project
-- fxcwkweaxjtknorudmwp) as the database owner. It signs in as a Platform Admin for the length of the statement only (set_config is local to it), then, for each
-- whole-set filter value (Description, Admission, Source tier, Website, Zoho), once over every provider and once with lifecycle_status = active:
--   (1) takes the total security.admin_providers_page_v3 answers and compares it with a plain SELECT count over the tables (Description and Admission admitted/held are
--       plain table queries that do not use the facts function; the rest are counted from security.provider_catalogue_facts_v1 over every provider), and
--   (2) when the total is 200 or less, compares the very set of provider ids on the page with the plain SELECT's ids.
--   It also times each request (milliseconds, wall clock). The block always ends in an exception that carries the result, so nothing persists.
-- Expected: "mismatches":0 and every row "same":true; "slowest_ms" far below the 8000 ms statement limit (the target is under 1000 on a quiet database).
-- The Platform Admin id below is the one the earlier equivalence script uses; replace it with any current Platform Admin's auth.users id if needed.
do $eq$
declare
  v_c jsonb; v_checks jsonb := $j$[{"name":"description filled (active)","kind":"plain table","args":{"description":"filled","lifecycle_status":"active","limit":200},"sql":"select p.id from catalogue.providers p where nullif(btrim(p.description),'') is not null and p.lifecycle_status='active'"},{"name":"description missing (active)","kind":"plain table","args":{"description":"missing","lifecycle_status":"active","limit":200},"sql":"select p.id from catalogue.providers p where nullif(btrim(p.description),'') is null and p.lifecycle_status='active'"},{"name":"admission admitted (active)","kind":"plain table","args":{"admission":"admitted","lifecycle_status":"active","limit":200},"sql":"select p.id from catalogue.providers p where nullif(btrim(p.description),'') is not null and (exists (select 1 from pipeline.provider_description_machine_admissions a where a.provider_id=p.id and a.outcome='admitted' and a.withdrawn_at is null and nullif(btrim(a.after_description),'')=nullif(btrim(p.description),'')) or exists (select 1 from pipeline.provider_description_reads r where r.provider_id=p.id and r.state in ('admitted','verified') and nullif(btrim(r.proposal->>'description'),'')=nullif(btrim(p.description),''))) and p.lifecycle_status='active'"},{"name":"admission held (active)","kind":"plain table","args":{"admission":"held","lifecycle_status":"active","limit":200},"sql":"select p.id from catalogue.providers p join lateral (select r.state, r.rule, r.review_item_id from pipeline.provider_description_reads r where r.provider_id=p.id order by r.created_at desc, r.id desc limit 1) lr on true where nullif(btrim(p.description),'') is null and lr.state in ('held','dead_letter') and coalesce(lr.rule,'') not like 'machine\\_declined%' and not coalesce(lr.review_item_id = (select a.review_item_id from pipeline.provider_description_machine_admissions a where a.provider_id=p.id and a.outcome='declined' order by a.created_at desc, a.id desc limit 1), false) and p.lifecycle_status='active'"},{"name":"admission pending (active)","kind":"facts, all providers","args":{"admission":"pending","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.admission_state='pending' and p.lifecycle_status='active'"},{"name":"admission declined (active)","kind":"facts, all providers","args":{"admission":"declined","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.admission_state='declined' and p.lifecycle_status='active'"},{"name":"source tier stored (active)","kind":"facts, all providers","args":{"source_tier":"stored","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='stored' and p.lifecycle_status='active'"},{"name":"source tier direct (active)","kind":"facts, all providers","args":{"source_tier":"direct","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='direct' and p.lifecycle_status='active'"},{"name":"source tier firecrawl (active)","kind":"facts, all providers","args":{"source_tier":"firecrawl","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='firecrawl' and p.lifecycle_status='active'"},{"name":"source tier registry_factual (active)","kind":"facts, all providers","args":{"source_tier":"registry_factual","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='registry_factual' and p.lifecycle_status='active'"},{"name":"source tier unknown (active)","kind":"facts, all providers","args":{"source_tier":"unknown","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='unknown' and p.lifecycle_status='active'"},{"name":"website matched (active)","kind":"facts, all providers","args":{"website":"matched","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='matched' and p.lifecycle_status='active'"},{"name":"zoho matched (active)","kind":"facts, all providers","args":{"zoho":"matched","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='matched' and p.lifecycle_status='active'"},{"name":"website pending (active)","kind":"facts, all providers","args":{"website":"pending","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='pending' and p.lifecycle_status='active'"},{"name":"zoho pending (active)","kind":"facts, all providers","args":{"zoho":"pending","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='pending' and p.lifecycle_status='active'"},{"name":"website missing (active)","kind":"facts, all providers","args":{"website":"missing","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='missing' and p.lifecycle_status='active'"},{"name":"zoho missing (active)","kind":"facts, all providers","args":{"zoho":"missing","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='missing' and p.lifecycle_status='active'"},{"name":"website not_applicable (active)","kind":"facts, all providers","args":{"website":"not_applicable","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='not_applicable' and p.lifecycle_status='active'"},{"name":"zoho not_applicable (active)","kind":"facts, all providers","args":{"zoho":"not_applicable","lifecycle_status":"active","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='not_applicable' and p.lifecycle_status='active'"},{"name":"description filled (all)","kind":"plain table","args":{"description":"filled","limit":200},"sql":"select p.id from catalogue.providers p where nullif(btrim(p.description),'') is not null"},{"name":"description missing (all)","kind":"plain table","args":{"description":"missing","limit":200},"sql":"select p.id from catalogue.providers p where nullif(btrim(p.description),'') is null"},{"name":"admission admitted (all)","kind":"plain table","args":{"admission":"admitted","limit":200},"sql":"select p.id from catalogue.providers p where nullif(btrim(p.description),'') is not null and (exists (select 1 from pipeline.provider_description_machine_admissions a where a.provider_id=p.id and a.outcome='admitted' and a.withdrawn_at is null and nullif(btrim(a.after_description),'')=nullif(btrim(p.description),'')) or exists (select 1 from pipeline.provider_description_reads r where r.provider_id=p.id and r.state in ('admitted','verified') and nullif(btrim(r.proposal->>'description'),'')=nullif(btrim(p.description),'')))"},{"name":"admission held (all)","kind":"plain table","args":{"admission":"held","limit":200},"sql":"select p.id from catalogue.providers p join lateral (select r.state, r.rule, r.review_item_id from pipeline.provider_description_reads r where r.provider_id=p.id order by r.created_at desc, r.id desc limit 1) lr on true where nullif(btrim(p.description),'') is null and lr.state in ('held','dead_letter') and coalesce(lr.rule,'') not like 'machine\\_declined%' and not coalesce(lr.review_item_id = (select a.review_item_id from pipeline.provider_description_machine_admissions a where a.provider_id=p.id and a.outcome='declined' order by a.created_at desc, a.id desc limit 1), false)"},{"name":"admission pending (all)","kind":"facts, all providers","args":{"admission":"pending","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.admission_state='pending'"},{"name":"admission declined (all)","kind":"facts, all providers","args":{"admission":"declined","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.admission_state='declined'"},{"name":"source tier stored (all)","kind":"facts, all providers","args":{"source_tier":"stored","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='stored'"},{"name":"source tier direct (all)","kind":"facts, all providers","args":{"source_tier":"direct","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='direct'"},{"name":"source tier firecrawl (all)","kind":"facts, all providers","args":{"source_tier":"firecrawl","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='firecrawl'"},{"name":"source tier registry_factual (all)","kind":"facts, all providers","args":{"source_tier":"registry_factual","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='registry_factual'"},{"name":"source tier unknown (all)","kind":"facts, all providers","args":{"source_tier":"unknown","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.source_tier='unknown'"},{"name":"website matched (all)","kind":"facts, all providers","args":{"website":"matched","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='matched'"},{"name":"zoho matched (all)","kind":"facts, all providers","args":{"zoho":"matched","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='matched'"},{"name":"website pending (all)","kind":"facts, all providers","args":{"website":"pending","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='pending'"},{"name":"zoho pending (all)","kind":"facts, all providers","args":{"zoho":"pending","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='pending'"},{"name":"website missing (all)","kind":"facts, all providers","args":{"website":"missing","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='missing'"},{"name":"zoho missing (all)","kind":"facts, all providers","args":{"zoho":"missing","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='missing'"},{"name":"website not_applicable (all)","kind":"facts, all providers","args":{"website":"not_applicable","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.website_state='not_applicable'"},{"name":"zoho not_applicable (all)","kind":"facts, all providers","args":{"zoho":"not_applicable","limit":200},"sql":"select f.provider_id from security.provider_catalogue_facts_v1(null,true) f join catalogue.providers p on p.id=f.provider_id where f.zoho_state='not_applicable'"}]$j$::jsonb;
  v_exp bigint; v_tot bigint; v_ids_exp uuid[]; v_ids_got uuid[]; v_r jsonb; v_t0 timestamptz; v_ms int; v_same boolean; v_idsame boolean;
  v_out jsonb := '[]'; v_bad int := 0; v_max int := 0;
begin
  perform set_config('request.jwt.claim.sub', 'c2882478-8a06-4cb5-9856-407d29e2fadb', true);
  perform set_config('request.jwt.claims', '{"sub":"c2882478-8a06-4cb5-9856-407d29e2fadb","role":"authenticated"}', true);
  if security.current_role_rank() < 6 then raise exception 'sign in as a Platform Admin: rank is %', security.current_role_rank(); end if;
  for v_c in select * from jsonb_array_elements(v_checks) loop
    execute 'select count(*), array_agg(q.id order by q.id) from (' || (v_c->>'sql') || ') q' into v_exp, v_ids_exp;
    v_t0 := clock_timestamp();
    v_r := security.admin_providers_page_v3(v_c->'args');
    v_ms := round(extract(epoch from clock_timestamp() - v_t0) * 1000);
    v_max := greatest(v_max, v_ms);
    v_tot := (v_r->>'total')::bigint;
    v_same := v_tot = v_exp;
    v_idsame := true;
    if v_exp <= 200 then
      select array_agg((i->>'id')::uuid order by (i->>'id')::uuid) into v_ids_got from jsonb_array_elements(v_r->'items') i;
      v_idsame := coalesce(v_ids_got, '{}') = coalesce(v_ids_exp, '{}');
    end if;
    if not (v_same and v_idsame) then v_bad := v_bad + 1; end if;
    v_out := v_out || jsonb_build_object('name', v_c->>'name', 'plain', v_c->>'kind', 'expected', v_exp, 'total', v_tot, 'same', v_same and v_idsame, 'ms', v_ms);
  end loop;
  raise exception 'FILTER EQUIVALENCE {"requests":%, "mismatches":%, "slowest_ms":%, "rows":%}', jsonb_array_length(v_out), v_bad, v_max, v_out::text;
end $eq$;
